const root=document.documentElement,themeButton=document.querySelector('#theme-toggle'),reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function updateThemeButton(){const dark=root.dataset.theme==='dark';themeButton.setAttribute('aria-label',dark?'Ativar tema claro':'Ativar tema escuro');themeButton.setAttribute('aria-pressed',String(!dark));themeButton.querySelector('.theme-label').textContent=dark?'CLARO':'ESCURO';themeButton.querySelector('.theme-icon').textContent=dark?'☼':'◐';document.querySelector('meta[name="theme-color"]').content=dark?'#141514':'#f2f3ed';}updateThemeButton();
let themeTimer;themeButton.addEventListener('click',()=>{clearTimeout(themeTimer);const next=root.dataset.theme==='dark'?'light':'dark',wipe=document.querySelector('.theme-wipe');wipe.classList.remove('run');void wipe.offsetWidth;if(!reducedMotion.matches)wipe.classList.add('run');root.dataset.theme=next;try{localStorage.setItem('axis-theme',next);}catch{}updateThemeButton();window.dispatchEvent(new CustomEvent('axis-theme',{detail:next}));themeTimer=setTimeout(()=>wipe.classList.remove('run'),750);});
const navigation=document.querySelector('#navigation'),menuButton=document.querySelector('#menu-toggle');let previousOverflow='';menuButton.addEventListener('click',()=>{previousOverflow=document.body.style.overflow;navigation.showModal();document.body.style.overflow='hidden';menuButton.setAttribute('aria-expanded','true');});function closeNavigation(){navigation.close();}document.querySelector('#menu-close').addEventListener('click',closeNavigation);navigation.addEventListener('close',()=>{document.body.style.overflow=previousOverflow;menuButton.setAttribute('aria-expanded','false');menuButton.focus({preventScroll:true});});navigation.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeNavigation));
const shapeNames=['01 — LOOP','02 — ÓRBITA','03 — NÚCLEO'];document.querySelectorAll('[data-shape]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-shape]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));document.querySelector('#shape-label').textContent=shapeNames[Number(button.dataset.shape)];window.dispatchEvent(new CustomEvent('axis-shape',{detail:Number(button.dataset.shape)}));}));
let scrollScheduled=false;function updateScroll(){const max=document.documentElement.scrollHeight-window.innerHeight;document.querySelector('.scroll-progress').style.transform=`scaleX(${max>0?window.scrollY/max:0})`;scrollScheduled=false;}window.addEventListener('scroll',()=>{if(!scrollScheduled){scrollScheduled=true;requestAnimationFrame(updateScroll);}},{passive:true});updateScroll();
